WITH revenue AS (
 SELECT c.name,SUM(o.quantity*p.price) AS paid_revenue
 FROM store_customers c JOIN store_orders o ON o.customer_id=c.id
 JOIN store_products p ON p.id=o.product_id
 WHERE o.status='paid' GROUP BY c.id,c.name
) SELECT name,paid_revenue,DENSE_RANK() OVER(ORDER BY paid_revenue DESC) AS revenue_rank FROM revenue;

